<script setup lang="ts">
import { ref, onMounted, onUnmounted, watch } from 'vue';
import axios from 'axios';
import {startRealtime,stopRealtime} from './realtime';
import { RouterLink, RouterView, useRoute, useRouter } from 'vue-router';
const route=useRoute(), router=useRouter();
const checking=ref(true);
const registering = ref(false), username = ref(''), password = ref(''), currentUser = ref(''), error = ref(''), busy = ref(false);
const api = axios.create({withCredentials:true});
async function csrf(){ const {data}=await api.get('/api/auth/csrf'); return {'X-XSRF-TOKEN':data.token}; }
let sessionRequest=0;
const authChannel=typeof BroadcastChannel==='undefined'?null:new BroadcastChannel('sdu-smart-life-auth');
async function restoreSession(){const request=++sessionRequest;checking.value=true;try{const {data}=await api.get('/api/auth/me');if(request===sessionRequest)currentUser.value=data.username;}catch{if(request===sessionRequest)currentUser.value='';}finally{if(request===sessionRequest){checking.value=false;refreshUnread();}}}
function profileUpdated(){restoreSession();avatarVersion.value++;}
function sessionReplaced(){currentUser.value='';router.replace('/');restoreSession();}
function authBroadcast(event:MessageEvent){if(event.data==='logout'){sessionRequest++;currentUser.value='';checking.value=false;router.replace('/');}else if(event.data==='login')sessionReplaced();}
onMounted(()=>{restoreSession();window.addEventListener('profile-updated',profileUpdated);window.addEventListener('session-replaced',sessionReplaced);if(authChannel)authChannel.onmessage=authBroadcast;});
const avatarVersion=ref(0),unreadCount=ref(0);
let unreadJob:Promise<void>|undefined,unreadAgain=false;
function refreshUnread(){unreadAgain=true;if(unreadJob)return unreadJob;unreadJob=(async()=>{while(unreadAgain){unreadAgain=false;const user=currentUser.value;if(!user){unreadCount.value=0;continue;}try{const {data}=await api.get('/api/notifications/unread');if(currentUser.value===user)unreadCount.value=data.count;}catch{}}})().finally(()=>unreadJob=undefined);return unreadJob;}
watch(currentUser,user=>{if(user)startRealtime();else{stopRealtime();unreadCount.value=0;}});
onMounted(()=>{window.addEventListener('notifications-updated',refreshUnread);window.addEventListener('realtime-update',refreshUnread);});
onUnmounted(()=>{stopRealtime();window.removeEventListener('notifications-updated',refreshUnread);window.removeEventListener('realtime-update',refreshUnread);window.removeEventListener('profile-updated',profileUpdated);window.removeEventListener('session-replaced',sessionReplaced);authChannel?.close();axios.interceptors.response.eject(authInterceptor);});
const authInterceptor=axios.interceptors.response.use(r=>r,e=>{if(e.response?.status===401){currentUser.value='';}return Promise.reject(e);});
async function submitAuth(){if(busy.value)return; busy.value=true;error.value='';try{const headers=await csrf();await api.post('/api/auth/'+(registering.value?'register':'login'),{username:username.value,password:password.value},{headers});if(registering.value){registering.value=false;error.value='注册成功，请登录';}else{await restoreSession();authChannel?.postMessage('login');}password.value='';}catch(e){error.value=axios.isAxiosError(e)&&e.response?.status===409?'用户名已存在':'操作失败，请检查账号密码或稍后重试';}finally{busy.value=false;}}
async function accountAction(){if(!currentUser.value){return;}try{await api.post('/api/auth/logout',null,{headers:await csrf()});sessionRequest++;currentUser.value='';authChannel?.postMessage('logout');router.replace('/');}catch{notice.value='退出失败，请稍后重试';}}
const notice = ref('');
function openSection(name: string) { if(name==='失物回家'){router.push('/lost-found');return;} if(name==='校园地图'){router.push('/campus');return;}  if(name==='个人主页'){router.push('/my/products');return;}  if(name==='二手市场'){router.push('/market');return;}  notice.value = `${name}正在迁移，完成后即可使用。`; }
</script>

<template>
 <main class="landing" :class="{'has-session':currentUser}">
  <p v-if="checking" class="session-check" role="status">正在确认登录状态…</p>
  <Teleport to="body"><header v-if="!checking && currentUser" class="navigation">
   <RouterLink class="brand" to="/" aria-label="智慧校园首页"><span class="brand-mark">山大</span><span>智慧校园<small>SDU SMART LIFE</small></span></RouterLink>
   <nav aria-label="主导航"><RouterLink to="/" :class="{active:route.path==='/'}">首页</RouterLink><button @click="openSection('二手市场')">二手市场</button><button @click="openSection('失物回家')">失物回家</button><button @click="openSection('校园地图')">校园地图</button><button @click="openSection('个人主页')">个人主页</button></nav>
   <div class="account"><RouterLink class="notification-bubble" to="/notifications" :aria-label="'消息中心，未读'+unreadCount+'条'"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4h16v12H9l-5 4V4Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><circle cx="8" cy="10" r="1" fill="currentColor"/><circle cx="12" cy="10" r="1" fill="currentColor"/><circle cx="16" cy="10" r="1" fill="currentColor"/></svg><b v-if="unreadCount>0">{{Math.min(99,unreadCount)}}</b></RouterLink><img :src="'/api/profile/avatar?v='+avatarVersion" alt=""><span>{{ currentUser }} · 已登录</span><button class="logout-button" @click="accountAction">退出登录</button></div>
  </header></Teleport>
  <div v-if="currentUser" class="page-content">
  <section v-if="currentUser && route.path==='/'" class="welcome">
   <p class="eyebrow"><span></span> SHANDONG UNIVERSITY · CAMPUS LIFE</p>
   <h1>在山大，<br>遇见生活的<span>更多可能。</span></h1>
   <p class="intro">让闲置好物继续陪伴，让熟悉的校园有新的发现。<br>你我的校园日常，在这里相连。</p>
   <div class="actions"><button class="primary" @click="openSection('二手市场')">逛逛二手市场 <span>↗</span></button><button class="secondary" @click="openSection('校园地图')">探索校园 <span>→</span></button></div>
  </section>
  <RouterView v-if="currentUser && route.path!=='/'" />
  <footer v-if="currentUser"><div><span class="location-dot"></span>中国 · 山东大学<small>每一份热爱，都值得在这里相遇</small></div><span class="footer-note">SDU SMART LIFE <i> / </i> 让校园生活更有温度</span></footer>
  </div>
  <div v-if="!checking && !currentUser" class="auth-overlay"><section class="auth-panel" role="dialog" aria-modal="true" aria-labelledby="auth-title"><p class="auth-kicker">山东大学 · SDU SMART LIFE</p><h2 id="auth-title">{{ registering ? '注册校园账号' : '登录智慧校园' }}</h2><form @submit.prevent="submitAuth"><label>用户名<input v-model="username" required pattern="[a-zA-Z0-9_-]{3,32}" autocomplete="username" placeholder="3–32 位字母、数字、下划线或短横线"></label><label>密码<input v-model="password" required type="password" minlength="8" maxlength="64" :autocomplete="registering?'new-password':'current-password'" placeholder="8–64 位密码"></label><p role="status" class="auth-error">{{ error }}</p><button class="auth-submit" :disabled="busy">{{ busy?'处理中…':registering?'注册':'登录' }}</button></form><button class="auth-switch" @click="registering=!registering;error=''">{{ registering?'已有账号？去登录':'没有账号？立即注册' }}</button></section></div>
  <div v-if="notice" class="notice" role="status">{{ notice }}<button aria-label="关闭提示" @click="notice = ''">×</button></div>
 </main>
</template>

<style>

*{box-sizing:border-box}body{margin:0;font-family:"Microsoft YaHei","PingFang SC",sans-serif;background:#18232b}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:2px solid #edc990;outline-offset:6px}.landing{position:relative;isolation:isolate;min-height:100svh;color:#fff;display:flex;flex-direction:column;background:url('/assets/legacy/images/sdu.jpg') center center/cover no-repeat}.landing:before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(12,23,32,.76) 0%,rgba(12,23,32,.36) 55%,rgba(12,23,32,.12)),linear-gradient(0deg,rgba(7,18,28,.75),transparent 35%,transparent 75%,rgba(7,18,28,.4))}.navigation{height:106px;margin:0 5%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff30;gap:25px}.brand{display:flex;align-items:center;gap:13px;text-decoration:none;color:white;font-size:22px;letter-spacing:3px;font-weight:600;white-space:nowrap}.brand-mark{display:grid;place-items:center;width:49px;height:49px;border:1px solid #ffffff80;border-radius:50%;font-family:serif;font-size:18px;letter-spacing:2px}.brand small{display:block;font-size:9px;letter-spacing:2px;font-weight:400;margin-top:7px;color:#ffffffb0}nav{display:flex;gap:36px;height:100%;align-items:center}nav a,nav button{position:relative;color:#ffffffe0;text-decoration:none;border:0;background:none;font-size:14px;padding:15px 0}nav .active:after{content:"";position:absolute;bottom:0;left:calc(50% - 10px);width:20px;height:2px;background:#efcf99}nav button:hover{color:#efcf99}.account{display:flex;align-items:center;gap:10px;background:none;border:0;color:white;font-size:13px;white-space:nowrap}.account img{width:30px;height:30px;border-radius:50%;object-fit:cover;border:1px solid #ffffff70}.welcome{width:90%;margin:auto; padding:75px 0 90px}.eyebrow{font-size:11px;letter-spacing:3px;color:#f0d5ac;display:flex;align-items:center;gap:14px}.eyebrow>span{height:1px;width:34px;background:#d9b789}h1{font-size:clamp(42px,4.6vw,72px);font-weight:500;line-height:1.4;letter-spacing:3px;margin:27px 0 24px;text-shadow:0 2px 25px #0002}h1 span{color:#f1d3a5}.intro{font-size:15px;line-height:2.1;color:#ffffffe0;letter-spacing:1px}.actions{display:flex;gap:16px;margin-top:38px}.actions button{height:49px;padding:0 25px;border-radius:3px;font-size:14px;letter-spacing:1px}.actions span{margin-left:30px}.primary{background:#eed4ac;border:1px solid #eed4ac;color:#28323a}.primary:hover{background:#f9e4c5}.secondary{background:#ffffff0a;border:1px solid #ffffff70;color:white;backdrop-filter:blur(6px)}.secondary:hover{background:#ffffff20}footer{margin:0 5%;padding:24px 0 27px;border-top:1px solid #ffffff30;display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#ffffffe0;letter-spacing:1px}footer small{margin-left:24px;color:#ffffff8c;font-size:11px}.location-dot{display:inline-block;width:6px;height:6px;background:#e9c795;border-radius:50%;margin-right:10px}.footer-note{font-size:10px;color:#ffffff9c;letter-spacing:2px}.footer-note i{margin:0 12px;font-style:normal;color:#e9c795}.notice{position:fixed;bottom:95px;left:50%;transform:translateX(-50%);background:#fff;color:#293744;padding:16px 20px;border-radius:6px;box-shadow:0 8px 35px #0003;display:flex;gap:20px;align-items:center;font-size:14px;max-width:90%;z-index:10}.notice button{border:0;background:none;font-size:22px;color:#61707a}@media(min-width:1700px){.welcome{padding-left:4%}}@media(max-width:850px){.navigation{height:90px;flex-wrap:wrap;padding:15px 0;gap:10px}.brand{font-size:18px}.brand-mark{width:38px;height:38px}nav{order:3;width:100%;height:auto;justify-content:center;gap:25px}nav a,nav button{font-size:12px;padding:5px 0}.navigation{height:125px}.welcome{padding:60px 0}.eyebrow{font-size:9px;letter-spacing:1.5px}h1{font-size:42px;letter-spacing:1px}.intro{font-size:13px}.actions button{padding:0 15px;font-size:12px}.actions span{margin-left:12px}.footer-note,footer small{display:none}footer{font-size:11px}.landing{background-position:58% center}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
.auth-overlay{position:fixed;inset:0;background:#07121cb3;backdrop-filter:blur(8px);z-index:30;display:grid;place-items:center;padding:20px}.auth-panel{position:relative;width:min(440px,100%);padding:42px;background:#fffaf2;color:#283b3b;border-radius:12px;box-shadow:0 20px 80px #0005}.auth-kicker{font-size:10px;letter-spacing:3px;color:#9b7952}.auth-panel h2{font-size:28px;margin:20px 0 30px}.auth-panel label{display:block;font-size:13px;margin:18px 0}.auth-panel input{display:block;width:100%;margin-top:9px;border:1px solid #d7d7cf;background:white;border-radius:4px;padding:13px 10px;font:inherit}.auth-error{font-size:12px;color:#9b3d35;min-height:18px}.auth-submit{width:100%;padding:13px;background:#304b49;color:white;border:0;border-radius:4px}.auth-submit:disabled{opacity:.5}.auth-switch{display:block;margin:22px auto 0;border:0;background:none;color:#8c6b44;font-size:13px}
.session-check{margin:auto}.logout-button{border:1px solid #ffffff60;background:transparent;color:white;padding:7px 10px;border-radius:4px;font-size:11px}.navigation{flex-shrink:0;z-index:20;background:transparent;backdrop-filter:none;margin:0;padding:0 5%;border-bottom:0;position:fixed;left:0;right:0;top:0;transform:none;will-change:auto}.auth-overlay{background:linear-gradient(110deg,#172d3c55,#172d3c22);backdrop-filter:none}.auth-panel{background:#fffaf2f5}.auth-panel h2{font-size:28px}
.has-session{padding-top:106px}@media(max-width:850px){.has-session{padding-top:125px}}
/* Navigation and business content occupy separate viewport regions. */
html,body,#app{height:100%;overflow:hidden}.landing{height:100dvh;min-height:0;overflow:hidden}.page-content{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;scrollbar-gutter:stable}.page-content>.welcome{flex:1;flex-shrink:0}.page-content>footer{flex-shrink:0}.page-content>.market,.page-content>.my-products{flex:1 0 auto}.navigation{height:106px;max-height:106px;overflow:hidden}@media(max-width:850px){.navigation{height:125px;max-height:125px}}
.notification-bubble{position:relative;display:inline-flex;color:white;text-decoration:none;margin-right:12px}.notification-bubble svg{width:28px;height:28px}.notification-bubble b{position:absolute;right:-10px;top:-7px;min-width:17px;height:17px;border-radius:10px;padding:1px 4px;background:#d84b46;color:white;font-size:10px;text-align:center;line-height:15px}
@media(max-width:550px){.account{max-width:100%;min-width:0}.account>span{min-width:0;overflow:hidden;text-overflow:ellipsis}.account img,.account .notification-bubble,.account .logout-button{flex-shrink:0}}
</style>


<style>@media(min-width:851px) and (max-width:1200px){nav{gap:18px}.navigation{padding:0 3%;gap:15px}.brand{font-size:18px}}@media(max-width:550px){nav{gap:17px}nav a,nav button{font-size:11px}}</style>
